import { createHash, randomBytes } from "node:crypto";
import { createTokenManager, fileSidecar } from "./token-manager.js";

// ── OAuth constants (verified from /opt/homebrew/bin/qwen source) ──────────
const CLIENT_ID       = "f0304373b74a44d2b584a3fb70ca9e56";
const SCOPE           = "openid profile email model.completion";
const GRANT_TYPE      = "urn:ietf:params:oauth:grant-type:device_code";
const DEVICE_CODE_URL = "https://chat.qwen.ai/api/v1/oauth2/device/code";
const TOKEN_URL       = "https://chat.qwen.ai/api/v1/oauth2/token";

// ── Fallback base URL if resource_url is missing from stored auth ───────────
const DEFAULT_BASE_URL = "https://portal.qwen.ai/v1";

// ── Resolve base URL from resource_url (mirrors qwen CLI's getCurrentEndpoint)
function resolveBaseURL(resourceUrl) {
  if (!resourceUrl) return DEFAULT_BASE_URL;
  const base = resourceUrl.startsWith("http") ? resourceUrl : `https://${resourceUrl}`;
  return base.endsWith("/v1") ? base : `${base}/v1`;
}

// ── PKCE helpers ────────────────────────────────────────────────────────────
function generatePKCE() {
  const verifier  = randomBytes(32).toString("base64url");
  const challenge = createHash("sha256").update(verifier).digest("base64url");
  return { verifier, challenge };
}

// ── OAuth requests ──────────────────────────────────────────────────────────
async function requestDeviceCode(pkce) {
  const res = await fetch(DEVICE_CODE_URL, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      client_id:             CLIENT_ID,
      scope:                 SCOPE,
      code_challenge:        pkce.challenge,
      code_challenge_method: "S256",
    }),
  });
  if (!res.ok) throw new Error(`Device code request failed: ${res.status} ${await res.text()}`);
  return res.json();
}

async function pollToken(deviceCode, codeVerifier) {
  const res  = await fetch(TOKEN_URL, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      grant_type:    GRANT_TYPE,
      client_id:     CLIENT_ID,
      device_code:   deviceCode,
      code_verifier: codeVerifier,
    }),
  });
  const data = await res.json().catch(() => ({}));

  if (res.status === 400 && data.error === "authorization_pending") return { status: "pending" };
  if (res.status === 429  || data.error === "slow_down")            return { status: "slow_down" };
  if (!res.ok) throw new Error(`Token poll failed: ${data.error || res.status}`);

  return { status: "success", ...data };
}

// ── Shared token manager (one instance per process) ─────────────────────────
const tokenManager = createTokenManager({ sidecar: fileSidecar });

// ── Plugin ──────────────────────────────────────────────────────────────────
export const QwenPlugin = async () => {
  return {
    auth: {
      provider: "qwen",

      // Called on every API request to resolve credentials.
      // getAuth() returns the Auth object opencode stored after authorize().
      loader: async (getAuth) => {
        const auth = await getAuth();
        if (auth.type !== "oauth") return {};

        // resource_url is stored in accountId (the only extra field available
        // in the oauth result type). Falls back to DEFAULT_BASE_URL if absent.
        const baseURL = resolveBaseURL(auth.accountId);

        return {
          // Override the base URL dynamically from the token's resource_url.
          baseURL,
          // apiKey must be non-empty for the provider constructor; the real
          // auth is injected per-request by the fetch interceptor below.
          apiKey: "oauth",
          fetch: async (input, init) => {
            const credentials = await tokenManager.getValidCredentials(auth);
            let token = credentials.access;

            // Clone init so we can mutate headers and body.
            const headers = new Headers(init?.headers);
            headers.set("Authorization", `Bearer ${token}`);
            // Mimic the headers the official qwen CLI sends — the server uses
            // these to identify Qwen Code clients and grant them full quota.
            headers.set("X-DashScope-AuthType",     "qwen-oauth");
            headers.set("X-DashScope-CacheControl", "enable");
            headers.set("X-DashScope-UserAgent",    "QwenCode/0.11.1 (darwin; arm64)");

            // The portal.qwen.ai endpoint gates "free quota" vs "Qwen Code"
            // quota based on the presence of a system message in the request.
            // Without one, all requests return 429 insufficient_quota.
            // Inject a minimal system message when the payload has none.
            let body = init?.body;
            if (body) {
              try {
                const parsed = JSON.parse(typeof body === "string" ? body : new TextDecoder().decode(body));
                const msgs   = parsed.messages ?? [];
                if (!msgs.some(m => m.role === "system")) {
                  parsed.messages = [
                    { role: "system", content: "You are Qwen Code, an interactive CLI agent developed by Alibaba Group, specializing in software engineering tasks. Your primary goal is to help users safely and efficiently, adhering strictly to the following instructions and utilizing your available tools." },
                    ...msgs,
                  ];
                  body = JSON.stringify(parsed);
                }
              } catch {
                // Non-JSON body — leave as-is.
              }
            }

            // Make the initial request.
            const initialRequest = new Request(input, { ...init, headers, body });
            let response = await globalThis.fetch(initialRequest);

            // If the response indicates an authentication error, refresh the
            // token and retry. Only 401/403 are treated as auth errors; other
            // 4xx (e.g. 400 bad model, 422 validation) are returned as-is to
            // avoid wasting a token refresh on non-auth failures.
            if (response.status === 401 || response.status === 403) {
              const refreshedCredentials = await tokenManager.getValidCredentials(auth, true);
              const refreshedToken = refreshedCredentials.access;

              const refreshedHeaders = new Headers(init?.headers);
              refreshedHeaders.set("Authorization", `Bearer ${refreshedToken}`);
              refreshedHeaders.set("X-DashScope-AuthType",     "qwen-oauth");
              refreshedHeaders.set("X-DashScope-CacheControl", "enable");
              refreshedHeaders.set("X-DashScope-UserAgent",    "QwenCode/0.11.1 (darwin; arm64)");

              const retryRequest = new Request(input, { ...init, headers: refreshedHeaders, body });
              response = await globalThis.fetch(retryRequest);
            }

            return response;
          },
        };
      },

      methods: [
        {
          type:  "oauth",
          label: "Login with Qwen account",
          authorize: async () => {
            const pkce       = generatePKCE();
            const deviceAuth = await requestDeviceCode(pkce);

            const {
              device_code,
              verification_uri_complete,
              expires_in,
              interval = 5,
            } = deviceAuth;

            // Try to open the browser automatically; silently fall back if the
            // 'open' package is unavailable (e.g. headless / CLI-only env).
            // The URL is always displayed by opencode as a fallback.
            try {
              const { default: open } = await import("open");
              await open(verification_uri_complete);
            } catch {
              // ignore — opencode will still display the URL
            }

            return {
              url:          verification_uri_complete,
              instructions: "Authorize the application in your browser.",
              method:       "auto",
              callback: async () => {
                const expiresAt = Date.now() + expires_in * 1000;
                let   pollMs    = interval * 1000;

                while (Date.now() < expiresAt) {
                  await new Promise(r => setTimeout(r, pollMs));

                  const result = await pollToken(device_code, pkce.verifier);

                  if (result.status === "pending")   continue;
                  if (result.status === "slow_down") { pollMs += 5_000; continue; }

                  if (result.status === "success") {
                    return {
                      type:      "success",
                      access:    result.access_token,
                      refresh:   result.refresh_token,
                      expires:   Date.now() + result.expires_in * 1000,
                      // Carry resource_url through accountId so the loader
                      // can resolve the correct base URL dynamically.
                      accountId: result.resource_url,
                    };
                  }
                }

                return { type: "failed" };
              },
            };
          },
        },
        {
          type:  "api",
          label: "Enter DashScope API Key manually",
        },
      ],
    },
  };
};

export default QwenPlugin;
